    if abs(ev.imag)>1e-7 or not (.000001<ev.real<.99999):continue
    X=evec[:,j].real;X*=-np.sign(X[3]);X/=abs(X[3]);XR=U@X;XRout=SR@XR;XLin=Ui@XRout
    checks=[-(np.array([1,-1,1,0])@X),np.array([1,1,1,0])@XRout,beR@XR,beL@XLin]
